package io.github.fgillet4.seedbox;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("fgillet4-seedbox")
public interface SeedBoxConfig extends Config
{
	@ConfigItem(
		keyName = "showCount",
		name = "Show total count on item",
		description = "Show the total number of seeds on the seed box in your inventory",
		position = 0
	)
	default boolean showCount()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showHover",
		name = "Show tooltip on hover",
		description = "Show seed breakdown and GE value when hovering over the seed box",
		position = 1
	)
	default boolean showHover()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showGEValue",
		name = "Show GE value in tooltip",
		description = "Include total Grand Exchange value of seeds in the hover tooltip",
		position = 2
	)
	default boolean showGEValue()
	{
		return true;
	}
}

package io.github.fgillet4.seedbox;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import java.util.LinkedHashMap;
import java.util.Map;

@Slf4j
@PluginDescriptor(
	name = "Seed Box",
	description = "Shows seed counts and total GE value for your Seed Box on hover",
	tags = {"seed", "box", "farming", "inventory", "overlay", "value"}
)
public class SeedBoxPlugin extends Plugin
{
	static final int[] SEED_BOX_IDS = {
		ItemID.SEED_BOX,
		ItemID.SEED_BOX_OPEN,
		ItemID.SEEDBOX
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SeedBoxConfig config;

	@Inject
	private SeedBoxOverlay overlay;

	// itemId -> quantity, ordered by slot
	@Getter
	private final Map<Integer, Integer> seeds = new LinkedHashMap<>();

	@Provides
	SeedBoxConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SeedBoxConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		clientThread.invokeLater(this::readSeedBox);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		seeds.clear();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.SEED_BOX)
		{
			readSeedBox();
		}
	}

	private void readSeedBox()
	{
		ItemContainer container = client.getItemContainer(InventoryID.SEED_BOX);
		if (container == null)
		{
			// Container is only available while the UI is open — keep last known counts
			return;
		}
		seeds.clear();
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			seeds.merge(item.getId(), item.getQuantity(), Integer::sum);
		}
	}

	public int getTotalSeeds()
	{
		return seeds.values().stream().mapToInt(Integer::intValue).sum();
	}

	public long getTotalValue()
	{
		long total = 0;
		for (Map.Entry<Integer, Integer> entry : seeds.entrySet())
		{
			total += (long) entry.getValue() * itemManager.getItemPrice(entry.getKey());
		}
		return total;
	}
}

package io.github.fgillet4.seedbox;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.QuantityFormatter;

import java.awt.Color;
import java.awt.Graphics2D;
import java.util.Map;

class SeedBoxOverlay extends WidgetItemOverlay
{
	private static final String BR = "</br>";
	private static final Color VALUE_COLOR = Color.YELLOW;
	private static final Color COUNT_COLOR = new Color(0xFF, 0x90, 0x40);

	private final Client client;
	private final SeedBoxPlugin plugin;
	private final SeedBoxConfig config;
	private final ItemManager itemManager;
	private final TooltipManager tooltipManager;

	@Inject
	SeedBoxOverlay(Client client, SeedBoxPlugin plugin, SeedBoxConfig config,
		ItemManager itemManager, TooltipManager tooltipManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		this.tooltipManager = tooltipManager;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		boolean isSeedBox = false;
		for (int id : SeedBoxPlugin.SEED_BOX_IDS)
		{
			if (itemId == id)
			{
				isSeedBox = true;
				break;
			}
		}
		if (!isSeedBox)
		{
			return;
		}

		Map<Integer, Integer> seeds = plugin.getSeeds();

		if (config.showCount() && !seeds.isEmpty())
		{
			graphics.setFont(FontManager.getRunescapeSmallFont());
			String label = String.valueOf(plugin.getTotalSeeds());
			int x = widgetItem.getCanvasLocation().getX();
			int y = widgetItem.getCanvasLocation().getY() + 31;
			graphics.setColor(Color.BLACK);
			graphics.drawString(label, x + 1, y + 1);
			graphics.setColor(Color.WHITE);
			graphics.drawString(label, x, y);
		}

		if (config.showHover() && isHovered(widgetItem, client.getMouseCanvasPosition()))
		{
			renderTooltip(seeds);
		}
	}

	private void renderTooltip(Map<Integer, Integer> seeds)
	{
		if (seeds.isEmpty())
		{
			tooltipManager.add(new Tooltip("Empty"));
			return;
		}

		StringBuilder tb = new StringBuilder();
		boolean first = true;

		for (Map.Entry<Integer, Integer> entry : seeds.entrySet())
		{
			String name = itemManager.getItemComposition(entry.getKey()).getName();
			String count = ColorUtil.wrapWithColorTag(
				QuantityFormatter.formatNumber(entry.getValue()), COUNT_COLOR);

			if (!first)
			{
				tb.append(BR);
			}
			tb.append(name).append(": ").append(count);
			first = false;
		}

		if (config.showGEValue())
		{
			long value = plugin.getTotalValue();
			if (value > 0)
			{
				tb.append(BR);
				tb.append("GE Value: ").append(ColorUtil.wrapWithColorTag(
					QuantityFormatter.quantityToStackSize(value) + " gp", VALUE_COLOR));
			}
		}

		tooltipManager.add(new Tooltip(tb.toString()));
	}

	private boolean isHovered(WidgetItem widgetItem, Point mousePosition)
	{
		return widgetItem.getCanvasBounds().contains(mousePosition.getX(), mousePosition.getY());
	}
}
